// @generated by:gauntlet run:godseye-local-orchestration
import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { controlled } from "./helpers/agents-fixture.js";
import {
  expireAtPublication,
  expireAtSettlement,
  type OrchestrationFixture,
  orchestrationFixture,
} from "./helpers/orchestration-fixture.js";

describe("durable orchestration through real Foundation delegation", () => {
  let f: OrchestrationFixture;
  beforeEach(async () => {
    f = await orchestrationFixture();
  });
  afterEach(async () => {
    vi.restoreAllMocks();
    await f.store.close();
  });
  const dependent = () => ({ ...f.research, id: "followup", dependsOn: ["research"] });

  it("T-AC-704 admits only approved ready children through Foundation and preserves dependency order", async () => {
    const plan = await f.prepare({ steps: [...f.input.steps, dependent()] });
    await f.tick();
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(0);
    await f.approve(plan);
    await f.tick();
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(1);
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(f.profile.limits.maxCostMicros);
    await f.work();
    await f.tick();
    await f.work();
    await f.tick();

    const result = await f.detail(plan.plan.id);
    expect(result.state).toBe("succeeded");
    expect(result.children.map((child) => child.state)).toEqual(["succeeded", "succeeded"]);
    expect(new Set(result.children.map((child) => child.taskId)).size).toBe(2);
    expect(f.agentProvider.submissions.map((task) => task.input)).toEqual([
      f.research.input,
      f.research.input,
    ]);
  });

  it("T-AC-704 honors dependencies when the consumer is listed before its source", async () => {
    const plan = await f.prepare({
      steps: [
        { ...dependent(), input: "Follow-up after source" },
        { ...f.research, input: "Source must execute first" },
      ],
    });
    await f.approve(plan);
    for (let n = 0; n < 2; n++) {
      await f.tick();
      await f.work();
    }
    await f.tick();
    expect(f.agentProvider.submissions.map((task) => task.input)).toEqual([
      "Source must execute first",
      "Follow-up after source",
    ]);
    expect((await f.detail(plan.plan.id)).state).toBe("succeeded");
  });

  it("T-AC-705 concurrent ticks and a rebuilt coordinator retain one child identity", async () => {
    const plan = await f.prepare();
    await f.approve(plan);
    await Promise.all([f.tick(), f.build().orchestration.tick(), f.tick()]);
    const before = await f.detail(plan.plan.id);
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(1);
    await f.work();
    await f.build().orchestration.tick();
    await f.tick();
    expect((await f.detail(plan.plan.id)).children[0]?.taskId).toBe(before.children[0]?.taskId);
    expect(f.agentProvider.submissions).toHaveLength(1);
  });

  it("T-AC-705 recovers a committed admission whose response was lost without another child", async () => {
    const launch = f.infrastructure.agents.launchDelegated.bind(f.infrastructure.agents);
    const lostResponse = vi
      .spyOn(f.infrastructure.agents, "launchDelegated")
      .mockImplementationOnce(async (...args) => {
        await launch(...args);
        throw new Error("Synthetic lost admission response after commit");
      });
    const plan = await f.prepare();
    await f.approve(plan);
    await f.tick();
    lostResponse.mockRestore();
    await f.build().orchestration.tick();
    await f.work();
    await f.tick();
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(1);
    expect((await f.infrastructure.agents.overview(f.freshOwner())).tasks).toHaveLength(1);
    expect(f.agentProvider.submissions).toHaveLength(1);
    expect((await f.detail(plan.plan.id)).state).toBe("succeeded");
  });

  it.each(["revision", "epoch", "expiry"] as const)(
    "T-AC-706 fences queued delegated execution after %s changes",
    async (change) => {
      const plan = await f.prepare();
      await f.approve(plan);
      await f.tick();
      if (change === "revision")
        await f.store.db
          .update(schema.projects)
          .set({ revision: f.project.revision + 1 })
          .where(eq(schema.projects.id, f.project.id));
      if (change === "epoch")
        await f.infrastructure.foundation.advanceEpoch(
          f.freshOwner(),
          f.development.id,
          randomUUID(),
        );
      if (change === "expiry") f.clock.advance(300001);
      await f.work();
      await f.tick();
      expect(f.agentProvider.submissions).toHaveLength(0);
      expect((await f.detail(plan.plan.id)).state).not.toBe("succeeded");
    },
  );

  it("T-AC-707 cancels queued children and never dispatches their dependents", async () => {
    const plan = await f.prepare({ steps: [...f.input.steps, dependent()] });
    await f.approve(plan);
    await f.tick();
    await f.infrastructure.orchestration.cancel(f.freshOwner(), plan.plan.id, randomUUID());
    await f.work();
    await f.tick();
    expect(f.agentProvider.submissions).toHaveLength(0);
    expect((await f.detail(plan.plan.id)).state).toBe("cancelled");
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(1);
  });

  it("T-AC-707 cancels a durable child intent before a physical task exists", async () => {
    const launch = f.infrastructure.agents.launchDelegated.bind(f.infrastructure.agents);
    const entered = controlled<void>(),
      release = controlled<void>();
    vi.spyOn(f.infrastructure.agents, "launchDelegated").mockImplementationOnce(async (...args) => {
      entered.resolve();
      await release.promise;
      return launch(...args);
    });
    const plan = await f.prepare();
    await f.approve(plan);
    const tick = f.tick();
    try {
      await Promise.race([
        entered.promise,
        tick.then(() => {
          throw new Error("Delegated launch never entered");
        }),
      ]);
      await f.infrastructure.orchestration.cancel(f.freshOwner(), plan.plan.id, randomUUID());
    } finally {
      release.resolve();
      await tick;
    }
    await f.tick();
    expect((await f.detail(plan.plan.id)).state).toBe("cancelled");
    expect(f.agentProvider.submissions).toHaveLength(0);
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(0);
  });

  it("T-AC-707 masks a late successful provider result after owner cancellation", async () => {
    const entered = controlled<void>(),
      release = controlled<void>();
    f.agentProvider.submitScript = async (request) => {
      entered.resolve();
      await release.promise;
      return {
        state: "succeeded",
        providerRunId: `provider-${request.taskId}`,
        stopped: true,
        output: "Late revoked result",
      };
    };
    const plan = await f.prepare({ steps: [...f.input.steps, dependent()] });
    await f.approve(plan);
    await f.tick();
    const work = f.work();
    try {
      await Promise.race([
        entered.promise,
        work.then(() => {
          throw new Error("Provider never entered");
        }),
      ]);
      await f.infrastructure.orchestration.cancel(f.freshOwner(), plan.plan.id, randomUUID());
    } finally {
      release.resolve();
      await work;
    }
    await f.tick();
    await f.infrastructure.orchestration.reconcile(f.freshOwner(), plan.plan.id, randomUUID());
    await f.tick();
    const result = await f.detail(plan.plan.id),
      child = result.children[0];
    if (!child?.taskId) throw new Error("Missing retained child identity");
    expect(
      (await f.infrastructure.agents.detail(f.freshOwner(), child.taskId)).task.output,
    ).toBeNull();
    expect(result.state).not.toBe("succeeded");
    expect(result.children.find((row) => row.stepId === "followup")?.taskId).toBeNull();
    expect(f.agentProvider.submissions).toHaveLength(1);
  });

  it("T-AC-706 rolls back logical publication when the parent expires after the final result SQL", async () => {
    const plan = await f.prepare({ lifetimeSeconds: 30 });
    await f.approve(plan);
    await f.tick();
    const fence = expireAtPublication(f);
    try {
      await f.work();
    } finally {
      fence.restore();
    }
    expect(fence.reached()).toBe(true);
    const child = (await f.detail(plan.plan.id)).children[0];
    if (!child?.taskId) throw new Error("Missing retained child identity");
    expect(
      (await f.infrastructure.agents.detail(f.freshOwner(), child.taskId)).task.output,
    ).toBeNull();
    await f.tick();
    await f.infrastructure.orchestration.reconcile(f.freshOwner(), plan.plan.id, randomUUID());
    expect(
      (await f.infrastructure.agents.detail(f.freshOwner(), child.taskId)).task.output,
    ).toBeNull();
    expect(f.agentProvider.submissions).toHaveLength(1);
  });

  it("T-AC-706 rolls back late Foundation settlement after the final success audit SQL", async () => {
    const plan = await f.prepare({ lifetimeSeconds: 30, steps: [f.research, dependent()] });
    await f.approve(plan);
    await f.tick();
    const fence = expireAtSettlement(f);
    try {
      await f.work();
    } finally {
      fence.restore();
    }
    expect(fence.reached()).toBe(true);
    await f.tick();
    const before = await f.detail(plan.plan.id),
      child = before.children[0];
    if (!child?.taskId) throw new Error("Missing retained child identity");
    expect(before.state).not.toBe("succeeded");
    expect(before.children.find((row) => row.stepId === "followup")?.taskId).toBeNull();
    expect(
      (await f.infrastructure.agents.detail(f.freshOwner(), child.taskId)).task.output,
    ).toBeNull();
    expect(await f.store.db.select().from(schema.agentChatArtifacts)).toHaveLength(0);
    await f.infrastructure.orchestration.reconcile(f.freshOwner(), plan.plan.id, randomUUID());
    expect(
      (await f.infrastructure.agents.detail(f.freshOwner(), child.taskId)).task.output,
    ).toBeNull();
    expect(f.agentProvider.submissions).toHaveLength(1);
  });

  it.each(["failed", "unknown"] as const)(
    "T-AC-707 %s child blocks dependents and reconcile never resubmits",
    async (state) => {
      f.agentProvider.submitScript = async (request) => ({
        state,
        providerRunId: `provider-${request.taskId}`,
        stopped: state === "failed",
      });
      f.agentProvider.inspectScript = async (request) => ({
        state,
        providerRunId: request.providerRunId,
        stopped: state === "failed",
      });
      const plan = await f.prepare({ steps: [...f.input.steps, dependent()] });
      await f.approve(plan);
      await f.tick();
      await f.work();
      await f.tick();
      const before = await f.detail(plan.plan.id);
      expect(before.state).toBe(state);
      await f.infrastructure.orchestration.reconcile(f.freshOwner(), plan.plan.id, randomUUID());
      await f.tick();
      expect(f.agentProvider.submissions).toHaveLength(1);
      expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(1);
      expect(
        (await f.detail(plan.plan.id)).children.find((child) => child.stepId === "followup")
          ?.taskId,
      ).toBeNull();
    },
  );

  it("T-AC-707 retains uncertain cleanup after a provider stop throws and continues unrelated work", async () => {
    f.agentProvider.submitScript = async (request) => ({
      state: "unknown",
      stopped: false,
      providerRunId: `provider-${request.taskId}`,
    });
    f.agentProvider.stopScript = async () => {
      throw new Error("Synthetic stop transport failure");
    };
    const plan = await f.prepare();
    await f.approve(plan);
    await f.tick();
    await f.work();
    await f.tick();
    await f.infrastructure.orchestration.cancel(f.freshOwner(), plan.plan.id, randomUUID());
    const unrelated = await f.prepare({
      maxCostMicros: 0,
      steps: [
        {
          id: "question",
          dependsOn: [],
          kind: "clarification",
          question: "Unrelated owner question",
        },
      ],
    });
    await f.approve(unrelated);
    await f.tick();
    expect((await f.detail(plan.plan.id)).state).not.toBe("cancelled");
    expect((await f.detail(unrelated.plan.id)).state).toBe("waiting_clarification");
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(f.profile.limits.maxCostMicros);
    expect(f.agentProvider.submissions).toHaveLength(1);
  });
});
